# Lore test-command interface (lore_list_tests / lore_run_test).
# Written for this repo's Jest suite rather than adapted from the Vitest
# equivalent for a Vitest suite: the report shapes happen to match, but the
# invocations do not.
- id: hal-engine-jest
  name: HAL Engine Jest suite
  cwd: .
  description: >-
    The ts-jest unit suite over src/ and scripts/ (jest.config.js roots), run
    on every pull request in .github/workflows/ci.yml as the "Test" step.
    Selectors are "<repo-relative-file>::<full test name>" as emitted by the
    list command. Jest has no dry-run, so the list command executes the suite
    once with --json and derives every name from the report; it deliberately
    tolerates a red suite, since listing must not depend on the tests passing.
    The run command selects one test with --runTestsByPath plus an anchored,
    regex-escaped -t, and treats a selector that matches nothing as a failure
    rather than a green run of an empty suite. Neither command builds first:
    no test here reads dist/.
  list: node scripts/lore-list-tests.mjs
  run: node scripts/lore-run-test.mjs "{selector}"
  coverage_format: lcov
---
{
  "name": "@re-cinq/hal-engine",
  "version": "0.5.0",
  "type": "module",
  "description": "A generic AI chat server framework with pluggable providers, tools, and transport",
  "license": "Apache-2.0",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/re-cinq/HALEngine.git"
  },
  "bugs": {
    "url": "https://github.com/re-cinq/HALEngine/issues",
    "email": "security@re-cinq.com"
  },
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "default": "./dist/index.js"
    }
  },
  "files": [
    "dist"
  ],
  "engines": {
    "node": ">=22"
  },
  "publishConfig": {
    "access": "public"
  },
  "config": {
    "mongodbMemoryServer": {
      "version": "7.0.14",
      "downloadDir": "./node_modules/.cache/mongodb-binaries"
    }
  },
  "scripts": {
    "dev": "tsx watch example/server.ts",
    "build": "node --input-type=module -e \"import {rmSync} from 'node:fs'; rmSync('dist',{recursive:true,force:true})\" && tsc -p tsconfig.build.json",
    "prepare": "npm run build",
    "start": "node dist/index.js",
    "test": "node --experimental-vm-modules node_modules/jest/bin/jest.js",
    "test:coverage": "node --experimental-vm-modules node_modules/jest/bin/jest.js --coverage",
    "smoke": "bash scripts/smoke.sh",
    "typecheck": "tsc --noEmit",
    "typecheck:example": "tsc -p tsconfig.example.json",
    "eslint": "eslint --max-warnings 0 .",
    "lint:backlog": "eslint -c eslint.config.backlog.mjs .",
    "check:spec-links": "node scripts/check-spec-links.mjs",
    "spec:names": "node scripts/check-spec-anchor-names.mjs",
    "spec:names:fix": "node scripts/check-spec-anchor-names.mjs --fix",
    "check:spec-status": "node scripts/check-spec-status.mjs",
    "check:audit": "node scripts/check-audit.mjs",
    "check:action-pins": "node scripts/check-action-pins.mjs",
    "check:version": "bash scripts/check-version.sh",
    "docs:check": "node scripts/check-doc-blocks.mjs",
    "docs:check-paths": "node scripts/check-doc-paths.mjs",
    "docs:check-spikes": "node scripts/check-spike-status.mjs",
    "check:regions": "node scripts/check-doc-regions.mjs",
---
import type {IncomingMessage} from '../../types/messages.js';

const MAX_CONTENT_LENGTH = 10000;

interface ValidationSuccess {
  valid: true;
  data: IncomingMessage;
}

interface ValidationFailure {
  valid: false;
  error: string;
}

export type ValidationResult = ValidationSuccess | ValidationFailure;

export function validateMessage(payload: unknown): ValidationResult {
  if (typeof payload !== 'object' || payload === null) {
    return {valid: false, error: 'Message must be an object'};
  }

  const message = payload as Record<string, unknown>;

  if (typeof message.type !== 'string') {
    return {valid: false, error: 'Message must have a type field'};
  }

  const validate = Object.prototype.hasOwnProperty.call(VALIDATORS, message.type)
    ? VALIDATORS[message.type]
    : undefined;
  if (validate === undefined) {
    return {valid: false, error: `Unknown message type: ${message.type}`};
  }
  return validate(message);
}

const VALIDATORS: Record<string, (message: Record<string, unknown>) => ValidationResult> = {
  user_message: validateUserMessage,
  ping: validatePingMessage,
  list_sessions: validateListSessionsMessage,
};

function validateUserMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.content !== 'string') {
    return {valid: false, error: 'user_message must have content string'};
  }

  const trimmed = message.content.trim();

  if (trimmed.length === 0) {
    return {valid: false, error: 'Message content cannot be empty'};
  }

  if (message.content.length > MAX_CONTENT_LENGTH) {
    return {valid: false, error: `Message content too long (max ${MAX_CONTENT_LENGTH} chars)`};
  }

  return {
    valid: true,
    data: {
      type: 'user_message',
      content: message.content,
    },
  };
}

function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
  if (message.limit !== undefined && (!Number.isInteger(message.limit) || (message.limit as number) < 0)) {
    return {valid: false, error: 'list_sessions limit must be a non-negative integer'};
  }

  if (message.before !== undefined && (typeof message.before !== 'object' || message.before === null)) {
    return {valid: false, error: 'list_sessions before must be a cursor object'};
  }

  return {
    valid: true,
    data:
      message.limit === undefined ? {type: 'list_sessions'} : {type: 'list_sessions', limit: message.limit as number},
  };
}

function validatePingMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.timestamp !== 'number') {
    return {valid: false, error: 'ping must have timestamp number'};
  }

  return {
    valid: true,
    data: {
      type: 'ping',
      timestamp: message.timestamp,
    },
  };
}
